"""JSON helpers that match Go's encoding/json []byte (standard base64) convention."""

from __future__ import annotations

import base64
import json
from typing import Any


def encode_bytes(data: bytes | None) -> str | None:
    if data is None:
        return None
    return base64.b64encode(data).decode("ascii")


def decode_bytes(value: Any) -> bytes:
    if value is None:
        return b""
    if isinstance(value, bytes):
        return value
    if isinstance(value, list):
        return bytes(value)
    if isinstance(value, str):
        if value == "":
            return b""
        try:
            return base64.b64decode(value, validate=False)
        except Exception:
            return value.encode("utf-8")
    return json.dumps(value).encode("utf-8")


def dumps(payload: Any) -> str:
    return json.dumps(payload, separators=(",", ":"), ensure_ascii=False)


def loads(data: bytes | str) -> Any:
    if isinstance(data, bytes):
        data = data.decode("utf-8")
    return json.loads(data)

"""Environment and .env loading for protocol + Databricks MLflow."""

from __future__ import annotations

import os
from pathlib import Path


def repo_root() -> Path:
    raw = os.environ.get("ENTIRE_REPO_ROOT") or os.getcwd()
    return Path(raw).resolve()


def load_dotenv_files() -> None:
    try:
        from dotenv import load_dotenv
    except ImportError:
        load_dotenv = None  # type: ignore[assignment]

    candidates = [
        repo_root() / ".env",
        Path(__file__).resolve().parents[2] / ".env",
        Path.cwd() / ".env",
    ]
    seen: set[Path] = set()
    for path in candidates:
        resolved = path.resolve()
        if resolved in seen or not resolved.is_file():
            continue
        seen.add(resolved)
        if load_dotenv is not None:
            load_dotenv(resolved, override=False)
        else:
            _parse_dotenv(resolved)


def _parse_dotenv(path: Path) -> None:
    for line in path.read_text(encoding="utf-8").splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#") or "=" not in stripped:
            continue
        key, value = stripped.split("=", 1)
        key = key.strip()
        value = value.strip().strip('"').strip("'")
        os.environ.setdefault(key, value)

"""Entire Graph reverse-dependency loader."""

from __future__ import annotations

import json
import os
import shutil
import subprocess
from collections import defaultdict
from pathlib import Path
from typing import Iterable

from entire_agent_codetriage.env import repo_root


def normalize_path(path: str, root: Path | None = None) -> str:
    value = path.replace("\\", "/").strip()
    if root is not None:
        try:
            value = Path(path).resolve().relative_to(root.resolve()).as_posix()
        except Exception:
            value = Path(path).as_posix()
    return value.lstrip("./")


def load_reverse_graph(root: Path | None = None) -> dict[str, set[str]]:
    """Return file -> files that depend on it (reverse edges)."""
    repo = root or repo_root()
    fixture = os.environ.get("CODETRIAGE_GRAPH_JSON")
    if fixture and Path(fixture).is_file():
        return _from_fixture(Path(fixture), repo)
    local_fixture = repo / ".codetriage" / "graph.json"
    if local_fixture.is_file():
        return _from_fixture(local_fixture, repo)
    return _from_entire_graph(repo)


def _from_fixture(path: Path, repo: Path) -> dict[str, set[str]]:
    data = json.loads(path.read_text(encoding="utf-8"))
    edges = defaultdict(set)
    raw_edges = data.get("reverse_dependencies") or data.get("reverse") or data.get("edges") or data
    if isinstance(raw_edges, dict):
        for src, dests in raw_edges.items():
            if src in {"files", "symbols", "relations"}:
                continue
            src_n = normalize_path(str(src), repo)
            if isinstance(dests, dict):
                continue
            for dest in dests or []:
                edges[src_n].add(normalize_path(str(dest), repo))
    for relation in data.get("relations") or []:
        if not isinstance(relation, dict):
            continue
        src = relation.get("from") or relation.get("from_path") or relation.get("from_id")
        dest = relation.get("to") or relation.get("to_path") or relation.get("to_id")
        if src and dest:
            # A depends on B means B -> A in reverse graph.
            edges[normalize_path(str(dest), repo)].add(normalize_path(str(src), repo))
    return dict(edges)


def _from_entire_graph(repo: Path) -> dict[str, set[str]]:
    entire = shutil.which("entire")
    if not entire:
        return {}

    files: dict[str, str] = {}
    symbols: dict[str, str] = {}
    edges: dict[str, set[str]] = defaultdict(set)

    for args in (
        [entire, "graph", "edges", "--repo", str(repo), "--format", "ndjson"],
        [entire, "graph", "snapshot", "--repo", str(repo), "--format", "ndjson", "--worktree"],
    ):
        records = _run_ndjson(args)
        if records:
            _ingest_records(records, files, symbols, edges)
            if edges:
                break
    return dict(edges)


def _run_ndjson(args: list[str]) -> list[dict]:
    try:
        proc = subprocess.run(
            args,
            check=False,
            capture_output=True,
            text=True,
            timeout=60,
        )
    except (OSError, subprocess.TimeoutExpired):
        return []
    if proc.returncode != 0:
        return []
    records = []
    for line in proc.stdout.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            record = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(record, dict):
            records.append(record)
    return records


def _ingest_records(
    records: Iterable[dict],
    files: dict[str, str],
    symbols: dict[str, str],
    edges: dict[str, set[str]],
) -> None:
    for record in records:
        kind = record.get("record_type") or record.get("type")
        if kind == "file":
            record_id = str(record.get("id") or "")
            path = record.get("path") or record.get("file_path")
            if record_id and path:
                files[record_id] = normalize_path(str(path))
        elif kind == "symbol":
            record_id = str(record.get("id") or "")
            path = record.get("file_path") or record.get("path")
            if record_id and path:
                symbols[record_id] = normalize_path(str(path))
        elif kind == "relation":
            from_id = str(record.get("from_id") or record.get("from") or "")
            to_id = str(record.get("to_id") or record.get("to") or "")
            from_path = _resolve_path(from_id, files, symbols, record.get("from_path"))
            to_path = _resolve_path(to_id, files, symbols, record.get("to_path"))
            if from_path and to_path and from_path != to_path:
                # Reverse: dependents of `to` include `from`.
                edges[to_path].add(from_path)


def _resolve_path(
    record_id: str,
    files: dict[str, str],
    symbols: dict[str, str],
    explicit: object,
) -> str | None:
    if explicit:
        return normalize_path(str(explicit))
    if record_id in files:
        return files[record_id]
    if record_id in symbols:
        return symbols[record_id]
    if record_id.endswith((".py", ".go", ".ts", ".js", ".java", ".rs")):
        return normalize_path(record_id)
    return None

"""Databricks MLflow telemetry for ESI commit-gate runs."""

from __future__ import annotations

import os
from typing import Any

from entire_agent_codetriage.blast_radius import BlastRadius
from entire_agent_codetriage.env import load_dotenv_files


def log_esi_run(result: BlastRadius, extra: dict[str, Any] | None = None) -> bool:
    """Log ESI telemetry. Never raises — commit gating must not depend on MLflow."""
    load_dotenv_files()
    if os.environ.get("CODETRIAGE_DISABLE_MLFLOW") == "1":
        return False
    try:
        import mlflow
    except ImportError:
        return False

    tracking_uri = os.environ.get("MLFLOW_TRACKING_URI") or os.environ.get("DATABRICKS_HOST")
    if not tracking_uri:
        return False
    if tracking_uri.startswith("https://") and "databricks" in tracking_uri:
        tracking_uri = "databricks"

    try:
        mlflow.set_tracking_uri(tracking_uri)
        experiment = os.environ.get("MLFLOW_EXPERIMENT_NAME", "codetriage-esi")
        experiment_id = os.environ.get("MLFLOW_EXPERIMENT_ID")
        if experiment_id:
            mlflow.set_experiment(experiment_id=experiment_id)
        else:
            mlflow.set_experiment(experiment)

        with mlflow.start_run(run_name="codetriage-commit-gate"):
            mlflow.log_params(
                {
                    "esi_level": str(result.esi_level),
                    "blocked": str(result.blocked).lower(),
                    "seed_count": str(len(result.seeds)),
                }
            )
            mlflow.log_metrics(
                {
                    "esi_level": float(result.esi_level),
                    "impacted_count": float(result.impacted_count),
                    "depth": float(result.depth),
                    "blocked": 1.0 if result.blocked else 0.0,
                }
            )
            if extra:
                safe_params = {str(k): str(v)[:250] for k, v in extra.items()}
                mlflow.log_params(safe_params)
        return True
    except Exception:
        return False

"""start / stop / commit hook install + parse + ESI commit gate."""

from __future__ import annotations

import json
import os
import subprocess
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

from entire_agent_codetriage import HOOK_NAMES
from entire_agent_codetriage.blast_radius import BlastRadius, compute_blast_radius
from entire_agent_codetriage.env import repo_root
from entire_agent_codetriage.graph import normalize_path
from entire_agent_codetriage.telemetry import log_esi_run

HOOK_MARKER = ".codetriage/hooks.json"

EVENT_SESSION_START = 1
EVENT_TURN_END = 3
EVENT_SESSION_END = 5


def hook_marker_path(root: Path | None = None) -> Path:
    return (root or repo_root()) / HOOK_MARKER


def are_hooks_installed(root: Path | None = None) -> bool:
    path = hook_marker_path(root)
    if not path.is_file():
        return False
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
        return False
    names = data.get("hooks") or []
    return all(name in names for name in HOOK_NAMES)


def install_hooks(force: bool = False, local_dev: bool = False, root: Path | None = None) -> int:
    del local_dev  # protocol flag is a no-op
    repo = root or repo_root()
    path = hook_marker_path(repo)
    if path.is_file() and not force:
        if are_hooks_installed(repo):
            return 0
    path.parent.mkdir(parents=True, exist_ok=True)
    payload = {
        "agent": "codetriage",
        "hooks": list(HOOK_NAMES),
        "installed_at": _now(),
        "commands": {
            "start": "entire-agent-codetriage parse-hook --hook start",
            "stop": "entire-agent-codetriage parse-hook --hook stop",
            "commit": "entire-agent-codetriage parse-hook --hook commit",
        },
    }
    path.write_text(json.dumps(payload, indent=2) + "\n", encoding="utf-8")
    _write_git_commit_hook(repo)
    return len(HOOK_NAMES)


def uninstall_hooks(root: Path | None = None) -> None:
    repo = root or repo_root()
    path = hook_marker_path(repo)
    if path.is_file():
        path.unlink()
    git_hook = repo / ".git" / "hooks" / "pre-commit-codetriage"
    if git_hook.is_file():
        git_hook.unlink()


def parse_hook(hook_name: str, raw: bytes) -> dict[str, Any] | None:
    if not raw.strip():
        return None
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return None
    if not isinstance(payload, dict):
        return None

    session_id = str(payload.get("session_id") or "")
    event: dict[str, Any] = {
        "type": _event_type(hook_name),
        "session_id": session_id,
        "timestamp": payload.get("timestamp") or _now(),
    }
    if payload.get("session_ref"):
        event["session_ref"] = payload["session_ref"]
    if payload.get("user_prompt"):
        event["prompt"] = payload["user_prompt"]
    if payload.get("tool_input") is not None:
        event["tool_input"] = payload["tool_input"]

    if hook_name == "commit":
        result = evaluate_commit(payload)
        event["metadata"] = {
            "esi_level": str(result.esi_level),
            "impacted_count": str(result.impacted_count),
            "depth": str(result.depth),
            "blocked": "true" if result.blocked else "false",
            "decision": "block" if result.blocked else "allow",
        }
        if result.blocked:
            event["response_message"] = _rejection_message(result)
        log_esi_run(
            result,
            extra={"session_id": session_id, "hook": "commit"},
        )
    return event


def evaluate_commit(payload: dict[str, Any]) -> BlastRadius:
    files = identify_modified_files(payload)
    return compute_blast_radius(files)


def identify_modified_files(payload: dict[str, Any]) -> list[str]:
    files: list[str] = []
    raw_data = payload.get("raw_data")
    if isinstance(raw_data, dict):
        files.extend(_coerce_files(raw_data.get("files")))
        files.extend(_coerce_files(raw_data.get("modified_files")))
        files.extend(_coerce_files(raw_data.get("changed_files")))

    tool_input = payload.get("tool_input")
    if isinstance(tool_input, dict):
        for key in ("path", "file_path", "file", "filename"):
            if tool_input.get(key):
                files.append(str(tool_input[key]))
        files.extend(_coerce_files(tool_input.get("files")))
        files.extend(_coerce_files(tool_input.get("paths")))

    for key in ("modified_files", "files", "changed_files"):
        files.extend(_coerce_files(payload.get(key)))

    if not files:
        files.extend(_git_changed_files())

    repo = repo_root()
    normalized = []
    seen = set()
    for item in files:
        path = normalize_path(str(item), repo)
        if path and path not in seen:
            seen.add(path)
            normalized.append(path)
    return normalized


def write_hook_response(message: str) -> bytes:
    return (json.dumps({"message": message}, separators=(",", ":")) + "\n").encode("utf-8")


def _event_type(hook_name: str) -> int:
    mapping = {
        "start": EVENT_SESSION_START,
        "session-start": EVENT_SESSION_START,
        "session_start": EVENT_SESSION_START,
        "stop": EVENT_SESSION_END,
        "session-end": EVENT_SESSION_END,
        "session_end": EVENT_SESSION_END,
        "commit": EVENT_TURN_END,
    }
    return mapping.get(hook_name, EVENT_TURN_END)


def _rejection_message(result: BlastRadius) -> str:
    preview = ", ".join(result.impacted[:8])
    if len(result.impacted) > 8:
        preview += ", …"
    return (
        "CodeTriage blocked this commit: ESI Level 1 (CRITICAL). "
        f"Depth={result.depth} (>= {3} triggers) or impacted_files="
        f"{result.impacted_count} (>= {10} triggers). "
        f"Impacted: {preview}"
    )


def _coerce_files(value: Any) -> list[str]:
    if not value:
        return []
    if isinstance(value, str):
        return [value]
    if isinstance(value, list):
        return [str(item) for item in value if item]
    return []


def _git_changed_files() -> list[str]:
    root = repo_root()
    files: list[str] = []
    for args in (
        ["git", "-C", str(root), "diff", "--cached", "--name-only", "--diff-filter=ACMR"],
        ["git", "-C", str(root), "diff", "--name-only", "--diff-filter=ACMR"],
    ):
        try:
            proc = subprocess.run(args, check=False, capture_output=True, text=True, timeout=15)
        except (OSError, subprocess.TimeoutExpired):
            continue
        if proc.returncode == 0:
            files.extend(line.strip() for line in proc.stdout.splitlines() if line.strip())
    return files


def _write_git_commit_hook(repo: Path) -> None:
    git_dir = repo / ".git"
    if not git_dir.exists():
        return
    hooks_dir = git_dir / "hooks"
    hooks_dir.mkdir(parents=True, exist_ok=True)
    hook = hooks_dir / "pre-commit-codetriage"
    hook.write_text(
        "#!/bin/sh\n"
        "exec entire-agent-codetriage parse-hook --hook commit\n",
        encoding="utf-8",
    )
    try:
        os.chmod(hook, 0o755)
    except OSError:
        pass


def _now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

